row(9, 15, 'MATERIAL', f'AND I TURNED AND CAME DOWN FROM THE MOUNTAIN, AND THE MOUNTAIN WAS BURNING WITH FIRE, AND THE TWO TABLETS OF THE COVENANT WERE ON MY TWO HANDS. {HP(9, 15, (("ואפן", "וארד", "מן", "ההר"), "and I turned and came down from the mountain — 10:5 the doublet; Exodus 32:15 \'and Moses turned and came down\'"), (("וההר", "בער", "באש"), "and the mountain was burning with fire — 4:11, 5:23, 9:15 the book\'s three"), (("ושני", "לחת", "הברית", "על", "שתי", "ידי"), "and the two tablets of the covenant on my two hands — [2, 2] the parser; Exodus 32:15 \'in his hand\' (singular)"))} {AP(9, 15, (("וטורא", "בער", "באשתא"), "and the mountain burning with fire — \'eshata\', the theophany\'s fire"), (("ותרין", "לוחי", "קימא", "על", "תרתין", "ידי"), "and the two tablets of the covenant on my two hands"))}')
row(9, 16, 'MATERIAL', f'AND I LOOKED, AND BEHOLD, YOU HAD SINNED AGAINST THE LORD YOUR GOD; YOU HAD MADE YOURSELVES A MOLTEN CALF; YOU HAD TURNED ASIDE QUICKLY FROM THE WAY WHICH THE LORD COMMANDED YOU. {HP(9, 16, (("וארא", "והנה"), "and I looked, and behold — THE TORAH\'S ONE SEAT of the prophets\' vision formula (Ezekiel, Zechariah, Daniel)"), (("חטאתם", "ליהוה", "אלהיכם"), "you had sinned against the LORD your God — the plural throughout 9:16-25"), (("עשיתם", "לכם", "עגל", "מסכה"), "you had made yourselves a molten calf — Exodus 32:4, 32:8, 9:16, Nehemiah 9:18 the four; the calf NAMED here (9:12 \'a molten image\')"), (("סרתם", "מהר", "מן", "הדרך"), "you had turned aside quickly from the way — the fourth seat of the phrase"))} {AP(9, 16, (("וחזיתי", "והא", "חבתון", "קדם", "יי"), "and I saw, and behold, you had sinned BEFORE the LORD — the object made \'before\'"), (("עגל", "מתכא"), "a molten calf"), (("סטתון", "בפריע", "מן", "ארחא"), "you turned aside quickly from the way"))}')
row(9, 17, 'MATERIAL', f'AND I TOOK HOLD OF THE TWO TABLETS AND THREW THEM FROM MY TWO HANDS AND BROKE THEM BEFORE YOUR EYES. {HP(9, 17, (("ואתפש", "בשני", "הלחת"), "and I took hold of the two tablets — \'took hold\' the lemma\'s one narrative seat in the book; the article\'s \'the tablets\' as Exodus 32:19"), (("ואשלכם", "מעל", "שתי", "ידי"), "and I threw them from my two hands — Exodus 32:19 \'he threw from his hand\'"), (("ואשברם", "לעיניכם"), "and I broke them before your eyes — ONE TOKEN shared with Exodus 32:19: THE BREAKING RETOLD IN MOSES\' OWN WORDS (\'beneath the mountain\' there, \'before your eyes\' here)"))} {AP(9, 17, (("ואחדית", "בתרין", "לוחיא"), "and I seized the two tablets"), (("ורמיתנון", "מעל", "תרתין", "ידי"), "and I threw them from my two hands"), (("ותברתנון", "לעיניכון"), "and I broke them before your eyes"))} The Sifrei 357:44 reads \'before your eyes\' with 34:12\'s \'before the eyes of all Israel\' — the breaking among the wonders (the shelf below).')
row(9, 18, 'MATERIAL', f'AND I FELL DOWN BEFORE THE LORD AS AT THE FIRST, FORTY DAYS AND FORTY NIGHTS; BREAD I DID NOT EAT AND WATER I DID NOT DRINK, FOR ALL YOUR SIN WHICH YOU SINNED, TO DO WHAT IS EVIL IN THE EYES OF THE LORD, TO PROVOKE HIM. {HP(9, 18, (("ואתנפל", "לפני", "יהוה", "כראשנה"), "and I fell down before the LORD as at the first — the hithpael 9:18, 9:25 the Torah\'s two seats; the Sifrei 26:7 makes falling a name of prayer"), (("ארבעים", "יום", "וארבעים", "לילה"), "forty days and forty nights — the second forty (9:9 the first, 10:10 the third telling); Exodus 34:28 ten tokens shared"), (("על", "כל", "חטאתכם", "אשר", "חטאתם"), "for all your sin which you sinned — the one seat"), (("לעשות", "הרע", "בעיני", "יהוה", "להכעיסו"), "to do what is evil in the eyes of the LORD, to provoke Him — THE KINGS\' FORMULA (fifty-three in the DB) at its ONE Torah seat; \'to provoke Him\' 4:25, 9:18, 31:29"))} {AP(9, 18, (("ואשתטחית", "קדם", "יי", "כקדמתא"), "and I prostrated myself before the LORD as at the first"), (("על", "כל", "חוביכון", "די", "חבתון"), "for all your sins which you sinned"), (("למעבד", "דביש", "קדם", "יי", "לארגזא", "קדמוהי"), "to do what is evil before the LORD, to anger before Him"))}')
row(9, 19, 'MATERIAL', f'FOR I WAS AFRAID OF THE ANGER AND THE WRATH WITH WHICH THE LORD WAS ANGRY AGAINST YOU, TO DESTROY YOU; AND THE LORD HEARKENED TO ME THAT TIME ALSO. {HP(9, 19, (("כי", "יגרתי", "מפני", "האף", "והחמה"), "for I was afraid of the anger and the wrath — \'afraid\' 9:19 and 28:60 in the Torah; the pair 9:19 and Jeremiah 36:7"), (("אשר", "קצף", "יהוה", "עליכם"), "with which the LORD was angry against you — the qal (9:7-8, 22 the hiphil)"), (("וישמע", "יהוה", "אלי", "גם", "בפעם", "ההוא"), "and the LORD hearkened to me that time also — 9:19 and 10:10 the two seats; Exodus 32:14\'s \'the LORD repented of the evil\' told as hearkening (one token shared)"))} {AP(9, 19, (("ארי", "דחלית", "מקדם", "רגזא", "וחמתא"), "for I feared before the anger and the wrath"), (("וקביל", "יי", "צלותי"), "and the LORD ACCEPTED MY PRAYER — \'hearkened to me\' made the prayer\'s acceptance (9:19, 10:10 the two seats)"), (("אף", "בזמנא", "ההיא"), "at that time also"))}')
row(9, 20, 'MATERIAL', f'AND WITH AARON THE LORD WAS VERY ANGRY, TO DESTROY HIM; AND I PRAYED FOR AARON ALSO AT THAT TIME. {HP(9, 20, (("ובאהרן", "התאנף", "יהוה", "מאד", "להשמידו"), "and with Aaron the LORD was very angry, to destroy him — AARON\'S PERIL TOLD ONLY HERE (Exodus 32 has his making, not the anger at him); \'to destroy him\' the Bible\'s one seat"), (("ואתפלל", "גם", "בעד", "אהרן"), "and I prayed for Aaron also — the hithpael 9:20, 9:26 (the Torah\'s eight); \'for\' as Exodus 32:30 \'for your sin\'"), (("בעת", "ההוא"), "at that time — fifteen in the book"))} {AP(9, 20, (("ועל", "אהרן", "הוה", "רגז", "מן", "קדם", "יי"), "and against Aaron there was anger from before the LORD — the reverence again"), (("לשציותיה",), "to destroy him"), (("וצליתי", "אף", "על", "אהרן"), "and I prayed for Aaron also"))} The milluim and investiture ledgers already read Aaron\'s re-acceptance from this verse (the prior reads).')
row(9, 21, 'MATERIAL', f'AND YOUR SIN WHICH YOU HAD MADE, THE CALF, I TOOK AND BURNED IT WITH FIRE AND CRUSHED IT, GRINDING IT THOROUGHLY, UNTIL IT WAS FINE AS DUST; AND I THREW ITS DUST INTO THE BROOK THAT DESCENDS FROM THE MOUNTAIN. {HP(9, 21, (("ואת", "חטאתכם", "אשר", "עשיתם", "את", "העגל"), "and your sin which you had made, the calf — the sin named the object (the store\'s \'sin-offering\' gloss the homograph, rewritten by reference)"), (("לקחתי", "ואשרף", "אתו", "באש"), "I took and burned it with fire — Exodus 32:20\'s \'he burned with fire\'"), (("ואכת", "אתו", "טחון", "היטב"), "and crushed it, grinding thoroughly — TWO INFINITIVE ABSOLUTES side by side; \'crushed\' the Torah\'s three (1:44, Numbers 14:45 the Amorites\' beating)"), (("עד", "אשר", "דק", "לעפר"), "until it was fine as dust — Exodus 32:20\'s three tokens; \'fine\' 9:21, Exodus 32:20, 30:36 the incense"), (("ואשלך", "את", "עפרו", "אל", "הנחל"), "and I threw its dust into the brook — Exodus scatters it on the water and makes Israel drink; JOSIAH\'S KIN (2 Kings 23:6, 23:12 the Kidron, \'beat to dust\')"))} {AP(9, 21, (("נסבית", "ואוקדית", "יתיה", "בנורא"), "I took and burned it in FIRE — \'nura\', the burnings\' fire (the idols\', 7:5, 7:25, 12:3; the mountain\'s fire is \'eshata\')"), (("ושפית", "יתיה", "בשופינא", "יאות"), "and I FILED it with a FILE, well — the grinding made a filing, the tool supplied (Exodus 32:20\'s Onkelos the same)"), (("ורמת", "ית", "עפריה", "לנחלא"), "and I threw its dust into the brook"))}')
row(9, 22, 'MATERIAL', f'AND AT TABERAH AND AT MASSAH AND AT KIBROTH-HATTAAVAH YOU WERE PROVOKING THE LORD. {HP(9, 22, (("ובתבערה", "ובמסה", "ובקברת", "התאוה"), "and at Taberah and at Massah and at Kibroth-hattaavah — Taberah\'s second seat (Numbers 11:3), Massah\'s five, Kibroth\'s five (DEFECTIVE here and Numbers 33:16-17, plene 11:34-35); the three fires, testings and graves out of order (Massah before Taberah in the tape)"), (("מקצפים", "הייתם", "את", "יהוה"), "you were provoking the LORD — the participle; the hiphil\'s third seat"))} {AP(9, 22, (("ובדלקתא", "ובנסתא", "ובקברי", "דמשאלי"), "and at THE BURNING and at THE TESTING and at THE GRAVES OF THE ASKERS — the three names TRANSLATED, as at Numbers 11:3, 11:34 and Exodus 17:7 (there \'nisseta\' spelled with a yod)"), (("מרגזין", "הויתון", "קדם", "יי"), "you were angering before the LORD"))} The Numbers 11 ledger read both name-translations at their own seats (credited by name).')
row(9, 23, 'MATERIAL', f'AND WHEN THE LORD SENT YOU FROM KADESH-BARNEA, SAYING, GO UP AND POSSESS THE LAND WHICH I HAVE GIVEN YOU, YOU REBELLED AGAINST THE MOUTH OF THE LORD YOUR GOD AND DID NOT BELIEVE HIM AND DID NOT HEARKEN TO HIS VOICE. {HP(9, 23, (("ובשלח", "יהוה", "אתכם", "מקדש", "ברנע"), "and when the LORD sent you from Kadesh-barnea — the name\'s ten seats (four in the book; the store splits it)"), (("עלו", "ורשו", "את", "הארץ"), "go up and possess the land — the plural imperative (1:21\'s singular \'go up, possess\')"), (("ותמרו", "את", "פי", "יהוה", "אלהיכם"), "you rebelled against the mouth of the LORD your God — 1:26\'s five tokens; \'the LORD your God\' PLURAL here alone in the chapter"), (("ולא", "האמנתם", "לו"), "and did not believe Him — 1:32\'s \'you do not believe in the LORD\' the kin; the store\'s \'build-up\' gloss rewritten"), (("ולא", "שמעתם", "בקלו"), "and did not hearken to His voice"))} {AP(9, 23, (("מרקם", "גיאה"), "from REKEM GEAH — Kadesh-barnea by its Aramaic name (1:2, 1:19, 2:14, 9:23 the four seats)"), (("וסרבתון", "על", "גזרת", "מימרא", "דיי"), "you rebelled against THE DECREE OF THE WORD of the LORD — \'the mouth\' made the Memra\'s decree (1:43 the kin)"), (("ולא", "הימנתון", "ליה"), "and did not trust Him"), (("ולא", "קבלתון", "למימריה"), "and did not ACCEPT HIS WORD — \'His voice\' made His Memra"))}')
row(9, 24, 'CONTEXT', f'YOU HAVE BEEN REBELLIOUS WITH THE LORD FROM THE DAY I KNEW YOU. {HP(9, 24, (("ממרים", "הייתם", "עם", "יהוה"), "you have been rebellious with the LORD — 9:7\'s clause closing the list"), (("מיום", "דעתי", "אתכם"), "from the day I knew you — the one seat"))} {AP(9, 24, (("מסרבין", "הויתון", "קדם", "יי"), "rebellious before the LORD"), (("מיומא", "דידעית", "יתכון"), "from the day I knew you"))}')
row(9, 25, 'MATERIAL', f'AND I FELL DOWN BEFORE THE LORD THE FORTY DAYS AND THE FORTY NIGHTS THAT I FELL DOWN, BECAUSE THE LORD HAD SAID HE WOULD DESTROY YOU. {HP(9, 25, (("ואתנפל", "לפני", "יהוה"), "and I fell down before the LORD — 9:18 resumed after the list"), (("את", "ארבעים", "היום", "ואת", "ארבעים", "הלילה"), "THE forty days and THE forty nights — the article\'s form ONE in the Bible; [40, 40] the parser"), (("אשר", "התנפלתי"), "that I fell down — the perfect of the hithpael, the one seat"), (("כי", "אמר", "יהוה", "להשמיד", "אתכם"), "because the LORD had said He would destroy you — 9:8\'s and 9:19\'s \'to destroy you\'"))} {AP(9, 25, (("ואשתטחית", "קדם", "יי"), "and I prostrated myself before the LORD"), (("ית", "ארבעין", "יממין", "וית", "ארבעין", "לילון"), "the forty days and the forty nights"))} The Sifrei 26:7 makes this falling one of prayer\'s ten names.')
row(9, 26, 'MATERIAL', f'AND I PRAYED TO THE LORD AND SAID: LORD GOD, DO NOT DESTROY YOUR PEOPLE AND YOUR INHERITANCE WHOM YOU REDEEMED WITH YOUR GREATNESS, WHOM YOU BROUGHT OUT OF EGYPT WITH A MIGHTY HAND. {HP(9, 26, (("ואתפלל", "אל", "יהוה", "ואמר"), "and I prayed to the LORD and said — the one seat of the clause; the Sifrei 26:7\'s \'prayer\' name"), (("אדני", "יהוה"), "Lord GOD — the double Name, 3:24\'s and Abraham\'s (Genesis 15:2, 15:8): the Torah\'s four"), (("אל", "תשחת", "עמך", "ונחלתך"), "do not destroy Your people and Your inheritance — 9:26, 9:29 and SOLOMON\'S 1 Kings 8:51 (five tokens shared: the king quotes this telling, not Exodus\'s)"), (("אשר", "פדית", "בגדלך"), "whom You redeemed with Your greatness — \'You redeemed\' 9:26 and 21:8 the two seats"), (("אשר", "הוצאת", "ממצרים", "ביד", "חזקה"), "whom You brought out of Egypt with a mighty hand — Exodus 32:11 \'with great power and with a mighty hand\'"))} {AP(9, 26, (("וצליתי", "קדם", "יי", "ואמרית"), "and I prayed before the LORD and said"), (("יי", "אלהים"), "the LORD God — the double Name rendered as at 3:24 (the two seats)"), (("די", "פרקתא", "בתקפך"), "whom You redeemed with Your STRENGTH — greatness made strength"), (("בידא", "תקיפא"), "with a mighty hand"))} The second person SINGULAR returns at 26-29 — Moses\' \'You\' to God (three voices on one pronoun in the chapter).')
row(9, 27, 'MATERIAL', f'REMEMBER YOUR SERVANTS ABRAHAM, ISAAC AND JACOB; DO NOT TURN TO THE STUBBORNNESS OF THIS PEOPLE, NOR TO ITS WICKEDNESS, NOR TO ITS SIN. {HP(9, 27, (("זכר", "לעבדיך", "לאברהם", "ליצחק", "וליעקב"), "remember Your servants, Abraham, Isaac and JACOB — Exodus 32:13 \'remember Abraham, Isaac and ISRAEL Your servants\': the name changed, the servants moved first"), (("אל", "תפן", "אל", "קשי", "העם", "הזה"), "do not turn to the stubbornness of this people — \'stubbornness\' the Bible\'s ONE seat of the noun; \'do not turn to\' Numbers 16:15\'s form (Moses on Korah\'s offering)"), (("ואל", "רשעו", "ואל", "חטאתו"), "nor to its wickedness nor to its sin — the noun \'wickedness\' the Torah\'s one seat"))} {AP(9, 27, (("אדכר", "לעבדיך", "לאברהם", "ליצחק", "וליעקב"), "remember Your servants Abraham, Isaac and Jacob"), (("לא", "תתפני", "לקשיות", "עמא", "הדין"), "do not turn to the hardness of this people"), (("ולחוביהון", "ולחטאיהון"), "nor to their sins nor to their offenses — the singulars made plurals"))}')
row(9, 28, 'MATERIAL', f'LEST THE LAND FROM WHICH YOU BROUGHT US OUT SAY: BECAUSE THE LORD WAS NOT ABLE TO BRING THEM INTO THE LAND WHICH HE PROMISED THEM, AND BECAUSE HE HATED THEM, HE BROUGHT THEM OUT TO KILL THEM IN THE WILDERNESS. {HP(9, 28, (("פן", "יאמרו", "הארץ"), "lest the land say — the chapter\'s one \'lest\'; Exodus 32:12 \'why should the Egyptians say\', Numbers 14:15 \'the nations will say\'"), (("אשר", "הוצאתנו", "משם"), "from which You brought us out — the chapter\'s one \'we\'"), (("מבלי", "יכלת", "יהוה", "להביאם"), "because the LORD was not able to bring them — Numbers 14:16\'s clause, THE TWO SEATS, \'for lack of\' spelled two ways (מבלי / מבלתי)"), (("ומשנאתו", "אותם", "הוציאם"), "and because He hated them He brought them out — 1:27 \'in the LORD\'s hatred of us\' the people\'s own taunt"), (("להמתם", "במדבר"), "to kill them in the wilderness — THE TAUNT\'S FOURTH FORM (Exodus 32:12 the mountains; Numbers 14:16 slaughtered in the wilderness; 1:27 the Amorite\'s hand)"))} {AP(9, 28, (("דילמא", "יימרון", "דירי", "ארעא"), "lest THE INHABITANTS of the land say — the speaker supplied"), (("מדלית", "יוכלא", "דיי"), "because there was no ability of the LORD"), (("ומדסני", "יתהון", "אפקנון"), "and because He hated them He brought them out"), (("לקטלותהון", "במדברא"), "to kill them in the wilderness"))}')
